/**
 * Update a Page with Markdown intent type
 */
type NotionUpdatePageWithMarkdown = {
  /**
   * Page ID
   * Specify the ID of the Page to Update.
   *
   * **Example**:
   * ```
   * 59833787-2cf9-4fdf-8782-e53db20768a5
   * ```
   */
  pageId: string;

  /**
   * Title
   * The title of the page. Required if no properties are provided. Ignored if properties are provided with title.
   *
   */
  title?: string;

  /**
   * Properties
   * The property values to update for the page. The keys are the names or IDs of the property and the values are property values. If a page property ID is not included, then it is not changed.
   *
   * **Example**:
   * ```
   * {
   *  "title":[
   *    {
   *      "text":{
   *        "content":"My Page"
   *      }
   *    }
   *  ]
   *}
   * ```
   */
  properties?: string;

  /**
   * Markdown Content
   * The content to update the page with, in Markdown format. If Replace Existing Content is True, this will replace the existing content. If Replace Existing Content is False, this will append to the existing content.
   *
   * **Example**:
   * ```
   * # My Page
   *
   *This is the content of my page in **Markdown** format.
   *
   *- List item 1
   *- List item 2
   * ```
   */
  markdownContent?: string;

  /**
   * Replace Existing Content
   * If Yes, existing page content will be replaced. If No, new content will be appended.
   *
   */
  replaceExisting?: boolean;

  /**
   * Cover
   * The cover image of the new page, represented as an file object (https://developers.notion.com/reference/file-object).
   *
   * **Example**:
   * ```
   * {
   *  "external":{
   *    "url":"https://upload.wikimedia.org/wikipedia/commons/6/62/Tuscankale.jpg"
   *  }
   *}
   * ```
   */
  cover?: string;

  /**
   * Icon
   * The icon of the new page. Either an emoji object (https://developers.notion.com/reference/emoji-object) or an external file object (https://developers.notion.com/reference/file-object).
   *
   * **Example**:
   * ```
   * {
   *  "emoji":"🥬"
   *}
   * ```
   */
  icon?: string;

  /**
   * Archived
   * Whether the page is archived (deleted). Set to true to archive a page. Set to false to un-archive (restore) a page.
   *
   */
  archived?: boolean;
};

/**
 * Update a Block intent type
 */
type NotionUpdateBlock = {
  /**
   * Block ID
   * Specify the ID of the Block to Update.
   *
   * **Example**:
   * ```
   * 9bc30ad4-9373-46a5-84ab-0a7845ee52e6
   * ```
   */
  blockId: string;

  /**
   * Archived
   * Set to true to archive (delete) a block. Set to false to un-archive (restore) a block.
   *
   */
  archived?: boolean;

  /**
   * Paragraph
   * Paragraph block objects contain the information within the paragraph property see the docs (https://developers.notion.com/reference/block#paragraph).
   *
   * **Example**:
   * ```
   * {
   *  "rich_text":[
   *    {
   *      "type":"text",
   *      "text":{
   *        "content":"Lacinato kale",
   *        "link":null
   *      }
   *    }
   *  ],
   *  "color":"default"
   *}
   * ```
   */
  paragraph?: string;

  /**
   * Image
   * Image block objects contain a file object (https://developers.notion.com/reference/file-object)detailing information about the image.
   *
   * **Example**:
   * ```
   * {
   *  "type":"external",
   *  "external":{
   *    "url":"https://website.domain/images/image.png"
   *  }
   *}
   * ```
   */
  image?: string;

  /**
   * Bookmark
   * Bookmark block objects contain the following information within the bookmark property see the docs (https://developers.notion.com/reference/block#bookmark)
   *
   * **Example**:
   * ```
   * {
   *  "caption":[],
   *  "url":"https://companywebsite.com"
   *}
   * ```
   */
  bookmark?: string;

  /**
   * Code
   * Code block objects contain the following information within the code property see the docs (https://developers.notion.com/reference/block#code)
   *
   * **Example**:
   * ```
   * {
   *  "rich_text":[
   *    {
   *      "type":"text",
   *      "text":{
   *        "content":"const a = 3"
   *      }
   *    }
   *  ],
   *  "language":"javascript"
   *}
   * ```
   */
  code?: string;

  /**
   * PDF
   * A PDF block object represents a PDF that has been embedded within a Notion page. It contains the following fields see the docs (https://developers.notion.com/reference/block#pdf)
   *
   * **Example**:
   * ```
   * {
   *  "type": "external",
   *  "external": {
   *      "url": "https://website.domain/files/doc.pdf"
   *  }
   *}
   * ```
   */
  pdf?: string;

  /**
   * Table
   * Table block objects are parent blocks for table row children. Table block objects contain the following fields within the table property see the docs (https://developers.notion.com/reference/block#table)
   *
   * **Example**:
   * ```
   * {
   *  "table_width":2,
   *  "has_column_header":false,
   *  "has_row_header":false
   *}
   * ```
   */
  table?: string;

  /**
   * Table of Contents
   * Table of contents block objects contain the following information within the table_of_contents property see the docs (https://developers.notion.com/reference/block#table-of-contents)
   *
   * **Example**:
   * ```
   * {
   *  "color":"default"
   *}
   * ```
   */
  tableOfContent?: string;

  /**
   * Additional Fields
   * Specify additional fields to include on this block as JSON see the docs (https://developers.notion.com/reference/block)
   *
   * **Example**:
   * ```
   * {
   *  "child_page":{
   *    "title":"Lacinato kale"
   *  },
   *  "child_database":{
   *    "title":"My database"
   *  }
   *}
   * ```
   */
  additionalFields?: string;
};

